assert all(old[p]==frozen[p] for p in scene)
text=(r/'engine/studio-core.mjs').read_text();marker='/** Independently optional 3D primitive source parsing.';prefix=text[:text.index(marker)].rstrip()+'\n';assert h(prefix.encode())==old['engine/studio-core.mjs']
lib=(r/'crates/viento-studio-core/src/lib.rs').read_text();blocks=['mod scene3d;\n','/// Independent strict 3D primitive source parsing; existing 2D domains remain valid.\n#[no_mangle]\npub extern "C" fn viento_core_scene3d_version() -> u32 {\n    1\n}\n\n','    Scene3DSuccess {\n        #[serde(rename = "protocolVersion")]\n        protocol_version: u32,\n        ok: bool,\n        scene3d: scene3d::Scene3DResponse,\n    },\n','    if operation == Some("scene3d.parse") {\n        let request = value.as_object().ok_or_else(CoreError::request)?;\n        if request.len() != 3 || !request.contains_key("content") {\n            return Err(CoreError::request());\n        }\n        return Ok(CoreResponse::Scene3DSuccess {\n            protocol_version: PROTOCOL_VERSION,\n            ok: true,\n            scene3d: scene3d::parse(request["content"].as_str().ok_or_else(CoreError::request)?)?,\n        });\n    }\n']
for block in blocks:assert lib.count(block)==1;lib=lib.replace(block,'')
assert h(lib.encode())==old['crates/viento-studio-core/src/lib.rs']
oldRust=[p for p in old if p.startswith('crates/viento-studio-core') and p!='crates/viento-studio-core/src/lib.rs'];assert all(old[p]==frozen[p] for p in oldRust)
history=read('historical-baseline.json');authors=read('author-baseline.json');assert len(history)==3457;assert len(authors)==39
for p,digest in history.items():assert h((r/p).read_bytes())==digest,p
for p,digest in authors.items():assert h((r/p).read_bytes())==digest,p
native=read('native-helpers.json');binaries=[]
for item in native['binaries']:
 p=Path(item['path']);bytes=p.read_bytes();assert len(bytes)==item['bytes'];assert h(bytes)==item['sha256'];binaries.append(item)
core=read('core-results.json');wasm=r/'engine/studio-core.wasm';bytes=wasm.read_bytes();assert len(bytes)==395888;assert h(bytes)==core['verification']['wasm']['sha256']
