 p=Path(file);stat=p.stat();bytes=p.read_bytes();assert len(bytes)==item['bytes'];assert h(bytes)==item['sha256'];assert stat.st_dev==item['dev'] and stat.st_ino==item['ino'];toolChecks[file]=item
